<script>
let orderData = [
  { name: '水煮鱼片', price: 42, qty: 1 },
  { name: '麻婆豆腐', price: 22, qty: 1 },
  { name: '白米饭', price: 4, qty: 2 }
];

function addToOrder(name, price) {
  const existing = orderData.find(item => item.name === name);
  if (existing) {
    existing.qty++;
  } else {
    orderData.push({ name, price, qty: 1 });
  }
  renderOrder();
}

function renderOrder() {
  const container = document.getElementById('orderItems');
  container.innerHTML = '';
  let subtotal = 0;
  orderData.forEach(item => {
    const total = item.price * item.qty;
    subtotal += total;
    container.innerHTML += `<div class="order-item"><span>${item.name} × ${item.qty}</span><span>¥${total}</span></div>`;
  });
  const final = Math.max(subtotal - 5, 0);
  document.getElementById('subtotal').textContent = '¥' + subtotal;
  document.getElementById('finalPrice').textContent = '¥' + final;
}
</script>

